package com.shopsphere;
import static org.junit.jupiter.api.Assertions.*;import java.util.UUID;import org.junit.jupiter.api.Test;import org.springframework.test.web.client.MockRestServiceServer;import org.springframework.web.client.RestClient;import static org.springframework.test.web.client.match.MockRestRequestMatchers.*;import static org.springframework.test.web.client.response.MockRestResponseCreators.*;
class HttpInventoryGatewayTest{@Test void reservesAndPropagatesCorrelationId(){var b=RestClient.builder();var server=MockRestServiceServer.bindTo(b).build();UUID id=UUID.randomUUID();server.expect(requestTo("http://inventory/api/inventory/"+id+"/reserve")).andExpect(method(org.springframework.http.HttpMethod.POST)).andRespond(withSuccess("{}",org.springframework.http.MediaType.APPLICATION_JSON));new HttpInventoryGateway(b.baseUrl("http://inventory").build()).reserve(id,2);server.verify();}@Test void doesNotRetryFailedReservation(){var b=RestClient.builder();var server=MockRestServiceServer.bindTo(b).build();UUID id=UUID.randomUUID();server.expect(org.springframework.test.web.client.ExpectedCount.once(),requestTo("http://inventory/api/inventory/"+id+"/reserve")).andRespond(withServerError());assertThrows(InventoryCommunicationException.class,()->new HttpInventoryGateway(b.baseUrl("http://inventory").build()).reserve(id,2));server.verify();}}
